from sku_text import sanitize_sku

def sanitize_sku_legacy(raw):
    """旧截断口径，仅历史回放脚本还在用。"""
    return raw[:12]

def post_inbound(raw_sku):
    sku = sanitize_sku(raw_sku)
    return {"sku": sku, "dock": "B2"}
